// Infused with creative algorithmic modifications.

// === Tab: mySketch ===
function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	background(10, 10, 15);
	stroke(uM_colors[2]);
	for (let i = 0; i < 1000; i++) {
		let x = randomGaussian(0.5, 0.13) * width;
		let y = randomGaussian(0.5, 0.13) * height;
		backInTheDay(x, y);
	}

	for (let i = 0; i < 100; i++) {
		var x = randomGaussian(0.5, 0.13) * width;
		var y = randomGaussian(0.5, 0.13) * height;
		let s = random(width) * random(random());
		strokeWeight(random(random()));
		if(random()<0.5){
			square(x, y, s);
		}else{
			circle(x, y, s);

		}
	}
}

function draw() {
  // === Variant 2: Organic Lissajous Morph ===
  scalePulse = 1.0 + 0.25 * sin(frameCount * 0.03);
  rotAngle = frameCount * 0.015;
  push();
  translate(width/2, height/2);
  rotate(rotAngle);
  scale(scalePulse);
  translate(-width/2, -height/2);



  pop();
}

function backInTheDay(x, y) {
	let c = int(random(10, 50));
	let scl = 0.005;
	let rnd = int(random(3));
	strokeWeight(random(random()));
	noFill();
	beginShape();
	if (rnd == 0) {
		for (let i = 0; i < c; i++) {
			let n = noise(x * scl, y * scl, i * 0.00001);
			let angle = int(n * 10) * (TAU / 4);
			vertex(x, y);
			x += cos(angle) * 8;
			y += sin(angle) * 8;
		}
		endShape();
	}
	else if (rnd == 1) {
		for (let i = 0; i < c; i++) {
			var n = noise(x * scl, y * scl, i * 0.00001);
			var angle = 10 * n;
			vertex(x, y);
			x += cos(angle) * 8;
			y += sin(angle) * 8;
		}
		endShape();
	}

	else if (rnd == 2) {
		for (let i = 0; i < c; i++) {
			var n = noise(x * scl, y * scl, i * 0.001);
			var angle = int(n * 15) * (TAU / 4);
			strokeWeight(random(random()));
			circle(x, y, random(random(10)));
			x += cos(angle) * 8;
			y += sin(angle) * 8;
		}
	}

	else if (rnd == 3) {
		for (let i = 0; i < c; i++) {
			var n = noise(x * scl, y * scl, i * 0.001);
			var angle = 15 * n;
			strokeWeight(random(random()));
			circle(x, y, random(random(10)));
			x += cos(angle) * 8;
			y += sin(angle) * 8;
		}
	}
}
